/**
 * Web app manifest: /aerolex/manifest.webmanifest
 * Lets the site open full screen, like an app, when added to a phone or tablet home screen.
 * Icons are generated by scripts/app-icons.mjs.
 */
import { withBase } from '../i18n/index.js';

export function GET() {
  const manifest = {
    id: withBase(''),
    name: 'AeroLex',
    short_name: 'AeroLex',
    start_url: withBase(''),
    scope: withBase(''),
    display: 'standalone',
    background_color: '#0A1628',
    theme_color: '#0A1628',
    icons: [
      { src: withBase('icons/icon-192.png'), sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: withBase('icons/icon-512.png'), sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: withBase('icons/icon-maskable-512.png'), sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
  };
  return new Response(JSON.stringify(manifest), { headers: { 'Content-Type': 'application/manifest+json' } });
}
